def update_one(docs, query, change):
    for doc in docs:
        if all(doc.get(k) == v for k, v in query.items()):
            doc.update(change.get('$set', {}))
            for field, amount in change.get('$inc', {}).items():
                doc[field] = doc.get(field, 0) + amount
            return 1
    return 0

