def update_many(docs, query, change):
    count = 0
    for doc in docs:
        if all(k in doc and doc[k] == v for k, v in query.items()):
            doc.update(change['$set'])
            count += 1
    return count

def delete_one(docs, query):
    for i, doc in enumerate(docs):
        if all(k in doc and doc[k] == v for k, v in query.items()):
            del docs[i]
            return 1
    return 0
